233	__device__ __forceinline__ float softmax_stats(float (&s)[CN/2], float* m_r, float* l_r, int r, int nb, float s2) {
234	    float b0 = -INFINITY, b1 = -INFINITY, b2 = -INFINITY, b3 = -INFINITY;
235	#pragma unroll
236	    for (int c = 0; c < CN / 8; c += 2) {
237	        b0 = fmaxf(b0, s[c*4+r*2+0]);     b1 = fmaxf(b1, s[c*4+r*2+1]);
238	        b2 = fmaxf(b2, s[(c+1)*4+r*2+0]); b3 = fmaxf(b3, s[(c+1)*4+r*2+1]);
239	    }
240	    float bm = fmaxf(fmaxf(b0, b1), fmaxf(b2, b3));
241	    bm = quad_max(bm);
242	    float scale_f;
243	    if (nb == 0) { m_r[r] = bm; scale_f = 1.f; }
244	    else { float prev = m_r[r]; m_r[r] = fmaxf(m_r[r], bm);
245	           float cur = (m_r[r] == -INFINITY) ? 0.f : m_r[r];
246	           scale_f = ex2_approx((prev - cur) * s2); l_r[r] *= scale_f; }
247	    float max_scaled = (m_r[r] == -INFINITY) ? 0.f : m_r[r] * s2;
248	    float ls0 = 0.f, ls1 = 0.f, ls2 = 0.f, ls3 = 0.f;
249	#pragma unroll
250	    for (int c = 0; c < CN / 8; c += 2) {
251	        float p0 = ex2_approx(s[c*4+r*2+0]     * s2 - max_scaled);
252	        float p1 = ex2_approx(s[c*4+r*2+1]     * s2 - max_scaled);
253	        float p2 = ex2_approx(s[(c+1)*4+r*2+0] * s2 - max_scaled);
254	        float p3 = ex2_approx(s[(c+1)*4+r*2+1] * s2 - max_scaled);
255	        s[c*4+r*2+0] = p0;     s[c*4+r*2+1] = p1;
256	        s[(c+1)*4+r*2+0] = p2; s[(c+1)*4+r*2+1] = p3;
257	        ls0 += p0; ls1 += p1; ls2 += p2; ls3 += p3;
258	    }
